-- =============================================
-- 商品服务数据库表结构
-- 数据库: ms-demo
-- 表名: goods_product (商品信息表)
-- 作者: hong
-- 创建时间: 2026-06-06
-- 修改说明: 主键ID改为BIGINT类型，使用雪花算法生成
-- =============================================

-- 删除已存在的表（如果存在）
DROP TABLE IF EXISTS goods_product;

-- 创建商品信息表
CREATE TABLE goods_product (
    -- 主键ID，使用雪花算法生成64位Long型ID
    id BIGINT NOT NULL PRIMARY KEY COMMENT '商品ID（雪花算法生成）',

    -- 商品基本信息
    product_name VARCHAR(200) NOT NULL COMMENT '商品名称',
    product_code VARCHAR(100) NOT NULL UNIQUE COMMENT '商品编码（SKU）',
    category_id BIGINT NOT NULL COMMENT '商品分类ID',
    category_name VARCHAR(100) NOT NULL COMMENT '商品分类名称',
    brand VARCHAR(100) COMMENT '商品品牌',

    -- 商品价格信息
    price DECIMAL(10, 2) NOT NULL COMMENT '商品价格（单位：元）',
    original_price DECIMAL(10, 2) COMMENT '商品原价（用于显示折扣）',
    cost_price DECIMAL(10, 2) COMMENT '成本价格',

    -- 库存信息
    stock_quantity INT NOT NULL DEFAULT 0 COMMENT '库存数量',
    frozen_stock INT NOT NULL DEFAULT 0 COMMENT '冻结库存（下单未支付）',

    -- 商品状态
    status SMALLINT NOT NULL DEFAULT 1 COMMENT '商品状态：0-下架 1-上架 2-售罄',
    is_deleted SMALLINT NOT NULL DEFAULT 0 COMMENT '是否删除：0-未删除 1-已删除',

    -- 商品描述
    description TEXT COMMENT '商品详细描述',
    specification VARCHAR(500) COMMENT '商品规格参数',
    images TEXT COMMENT '商品图片（JSON格式存储多个图片URL）',

    -- 销售信息
    sales_count INT NOT NULL DEFAULT 0 COMMENT '销量',
    comment_count INT NOT NULL DEFAULT 0 COMMENT '评论数',
    rating DECIMAL(3, 2) COMMENT '商品评分（0.00-5.00）',

    -- 审计字段
    create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    update_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
    create_by VARCHAR(64) COMMENT '创建人',
    update_by VARCHAR(64) COMMENT '更新人',

    -- 索引
    INDEX idx_product_code (product_code) COMMENT '商品编码索引',
    INDEX idx_category_id (category_id) COMMENT '分类ID索引',
    INDEX idx_status (status, is_deleted) COMMENT '状态索引',
    INDEX idx_create_time (create_time) COMMENT '创建时间索引'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商品信息表';

